namespace docking.widgets.table.constraint;



using docking.widgets.table.constraint.provider;

/**
 * Column Constraint where acceptable column values are greater than or equal to some specified
 * value of the column type.
 */
public class AtLeastDateColumnConstraint : SingleValueColumnConstraint<LocalDate> {

	/**
	 * Constructs a new AtLeasDateColumnConstraint with a default name, default group and a minimum value
	 *
	 * @param minValue the value for which all acceptable column values must be greater than or equal.
	 * @param editorProvider an object that can provide a ConstraintEditor for this constraint type.
	 */
	public AtLeastDateColumnConstraint(LocalDate minValue,
			EditorProvider<LocalDate> editorProvider) : base("On or After Date", minValue, editorProvider, "date")
    {
	}

	/* @Override */
	public bool accepts(LocalDate value, TableFilterContext context) {
		if (value == null) {
			return false;
		}
		return value.compareTo(getConstraintValue()) >= 0;
	}

	/* @Override */
	public SingleValueColumnConstraint<LocalDate> copy(LocalDate newValue) {
		return new AtLeastDateColumnConstraint(newValue, editorProvider);
	}

}
